// Walks the flow at 390 x 700 and, on each screen, reports what sits under
// the pinned footer at the top of the page and at the bottom of the scroll
import { chromium } from "playwright";

const BASE = process.env.BASE ?? "http://localhost:3400";
const OUT = new URL("./shots/", import.meta.url).pathname;
const H = Number(process.env.H ?? 700);

const browser = await chromium.launch({ channel: "chrome" });
const context = await browser.newContext({ viewport: { width: 390, height: H }, isMobile: true, hasTouch: true });
await context.route(/posthog\.com|\/ingest\//, (r) => r.abort());
const page = await context.newPage();

async function settle() {
  await page.waitForLoadState("load");
  await page.waitForTimeout(900);
}

async function measure(name) {
  await settle();
  const r = await page.evaluate(() => {
    const footer = document.querySelector("[data-pinned-footer]") ??
      [...document.querySelectorAll("div")].find((d) => getComputedStyle(d).position === "sticky" && getComputedStyle(d).bottom === "0px");
    const main = document.querySelector("main");
    const leaves = main ? [...main.querySelectorAll("p,h1,h2,h3,label,button,a,input,li,span")].filter((e) => {
      const b = e.getBoundingClientRect();
      const s = getComputedStyle(e);
      return b.height > 0 && b.width > 0 && s.visibility !== "hidden" && !e.closest("[aria-hidden=true]");
    }) : [];
    const check = () => {
      const f = footer?.getBoundingClientRect();
      if (!f) return [];
      return leaves
        .filter((e) => { const b = e.getBoundingClientRect(); return b.bottom > f.top + 1 && b.top < f.bottom && b.top < innerHeight; })
        .map((e) => (e.textContent || e.getAttribute("aria-label") || e.tagName).trim().slice(0, 50));
    };
    window.scrollTo(0, 0);
    const atTop = check();
    window.scrollTo(0, document.documentElement.scrollHeight);
    const atEnd = check();
    const f = footer?.getBoundingClientRect();
    return {
      page: document.documentElement.scrollHeight,
      inner: innerHeight,
      footerH: f ? Math.round(f.height) : null,
      footerPos: footer ? getComputedStyle(footer).position : null,
      atTop: [...new Set(atTop)].slice(0, 6),
      atEnd: [...new Set(atEnd)].slice(0, 6),
    };
  });
