  await page.evaluate(() => window.scrollTo(0, 0));
  await page.screenshot({ path: `${OUT}${name}-top.png` });
  console.log(`${name}: page ${r.page}/${r.inner}, footer ${r.footerH}px ${r.footerPos}\n  under footer at top: ${JSON.stringify(r.atTop)}\n  under footer at end: ${JSON.stringify(r.atEnd)}`);
}

