await hosp.getByText("No", { exact: true }).click();
await cont();
await page.waitForURL(/whats-going-on/);
await measure("05-whats-going-on");
await page.getByRole("textbox").fill("I was diagnosed with ADHD and my medication ran out");
await cont();
await page.waitForURL(/confirm/, { timeout: 60000 });
await page.waitForTimeout(1500);
await measure("06-confirm");
await page.getByRole("button", { name: "Looks right" }).click();
await page.waitForURL(/provider/, { timeout: 60000 });
await measure("07-provider");
await page.getByRole("button", { name: /^Book / }).click();
await page.waitForURL(/book$/, { timeout: 60000 });
await measure("08-details");
await cont();
await measure("09-details-errors");
await page.getByLabel("First and last name").fill("Sam Rivera");
await page.getByLabel("Email").fill(process.env.TAKEN ?? `test.${Date.now()}@example.com`);
await page.getByLabel("Mobile phone").fill("5125550142");
await page.getByText("I consent to treatment", { exact: false }).click();
await cont();
await page.waitForTimeout(2500);
if (!page.url().includes("payment")) await measure("10-details-taken");
else {
  await measure("10-payment");
  await page.getByRole("button", { name: "Book my visit" }).click();
  await measure("11-payment-errors");
}
await browser.close();

