// Books a visit with made-up details, so the portal and clinician view open.
// Shared by the repro scripts
export async function book(page, base) {
  const answer = (q, c) => page.getByRole("group", { name: q }).getByText(c, { exact: true }).click();
  const cont = () => page.getByRole("button", { name: "Continue", exact: true }).first().click();
  await page.goto(`${base}/join`);
  await page.getByLabel("Date of birth").pressSequentially("01151990");
  await answer("Will you be in Texas for your visits?", "Yes");
  await cont();
  await page.waitForURL(/insurance/);
  await answer("Do you have health insurance?", "Yes");
  await page.getByRole("radio", { name: "Aetna", exact: true }).click();
  await cont();
  await page.waitForURL(/your-plan/);
  await page.getByRole("link", { name: "Continue" }).first().click();
  await page.waitForURL(/safety/);
  await answer("Are you thinking about harming yourself or others?", "No");
  await page.getByRole("group").nth(1).getByText("No", { exact: true }).click();
  await cont();
  await page.waitForURL(/whats-going-on/);
  await page.getByRole("textbox").fill("I was diagnosed with ADHD and my medication ran out");
  await cont();
  await page.waitForURL(/confirm/, { timeout: 60000 });
  await page.getByRole("button", { name: "Looks right" }).first().click();
  await page.waitForURL(/provider/, { timeout: 60000 });
  await page.getByRole("button", { name: /^Book / }).first().click();
  await page.waitForURL(/book$/, { timeout: 60000 });
  await page.getByLabel("First and last name").fill("Sam Rivera");
  await page.getByLabel("Email").fill(`test.${Date.now()}.${Math.floor(Math.random() * 1e6)}@example.com`);
  await page.getByLabel("Mobile phone").fill("5125550142");
  await page.getByText("I consent to treatment", { exact: false }).click();
  await cont();
  await page.waitForURL(/payment/, { timeout: 60000 });
  await page.getByLabel("Card number").fill("4242424242424242");
  await page.getByLabel(/Expiry/).fill("1230");
  await page.getByLabel("Security code").fill("123");
  await page.getByLabel("ZIP code").fill("78701");
  await page.getByRole("button", { name: "Book my visit" }).first().click();
  await page.waitForURL(/booked/, { timeout: 60000 });
}

// Desktop: Demo controls, switch to the clinician view, then try to click
import { chromium } from "playwright";
import { book } from "./book.mjs";

const BASE = process.env.BASE ?? "http://localhost:3400";
const browser = await chromium.launch({ channel: "chrome" });
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
await context.route(/posthog\.com|\/ingest\//, (r) => r.abort());
const page = await context.newPage();
await book(page, BASE);
