import { chromium } from "playwright";
import { book } from "./book.mjs";

const BASE = process.env.BASE ?? "http://localhost:3400";
const browser = await chromium.launch({ channel: "chrome" });
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
await context.route(/posthog\.com|\/ingest\//, (r) => r.abort());
const page = await context.newPage();
await book(page, BASE);
await page.goto(`${BASE}/visit`);
await page.getByRole("button", { name: "Demo", exact: true }).click();
await page.waitForTimeout(600);
await page.getByRole("button", { name: "Mark visit completed" }).click();
await page.waitForTimeout(2500);
const demoOpen = await page.evaluate(() =>
  [...document.querySelectorAll("dialog")].some((d) => d.open && d.getAttribute("aria-labelledby") === "demo-controls-title" && d.checkVisibility()),
);
console.log("demo sheet open:", demoOpen);
try {
  await page.getByRole("group", { name: "How was your first visit?" }).getByRole("button", { name: "9", exact: true }).click({ timeout: 4000 });
  console.log("rating tap: ok");
} catch {
  console.log("rating tap: FAILED");
}
await page.screenshot({ path: new URL("./shots/rating.png", import.meta.url).pathname });
await browser.close();

