@import "tailwindcss";

/* Design tokens from Claude Design's handoff spec (the Main board, Oct 29).
   Values there are the source of truth; nothing here is styled one off. */
  --radius-tile: 16px;
  --radius-card: 20px;

  /* Control heights */
  --spacing-control: 3.375rem; /* 54px: the primary button */
  --spacing-field: 3.25rem; /* 52px: inputs and options */
  --spacing-control-sm: 2.75rem; /* 44px: chips, text-style buttons, tap targets */

  /* Content widths */
  --container-form: 37.5rem; /* 600px: questions and payment */
  --container-picker: 47.5rem; /* 760px: chip pickers, the clinician view */
  --container-wide: 53.75rem; /* 860px: provider and details */
  --container-notice: 39.5rem; /* 632px: screen-outs and the crisis screens */
  --container-panel: 20rem; /* 320px: the desktop path panel */
  --container-shell: 80rem; /* 1280px: the desktop top bar */

  /* Shadows */
  --shadow-card: 0 1px 2px rgb(6 27 77 / 0.04), 0 6px 20px rgb(6 27 77 / 0.06);
  --shadow-notice: 0 1px 2px rgb(6 27 77 / 0.04), 0 12px 32px rgb(6 27 77 / 0.08);
  --shadow-card-hover: 0 2px 4px rgb(6 27 77 / 0.06), 0 10px 28px rgb(6 27 77 / 0.1);
  --shadow-sheet: 0 -12px 40px rgb(6 27 77 / 0.18);
  --shadow-dialog: 0 24px 64px rgb(6 27 77 / 0.24);

  /* Motion: the spec's spring (no bounce), exit and settle */
  --ease-spring: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);
  --ease-settle: cubic-bezier(0.34, 1.32, 0.64, 1);
}

/* Keyboard focus on everything: 3px action blue, 2px offset */
@utility focus-ring {
  &:focus-visible {
    outline: 3px solid var(--color-action);
    outline-offset: 2px;
  }
}

/* A white card behind anything people read */
@utility card {
  background: var(--color-white);
  border: 1px solid var(--color-card-line);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
}

@layer base {
  :root {
    color-scheme: light;
    --in: 0.45s;
    --out: 0.28s;
    --press: 0.12s;
    --step: 60ms;
  }

  body {
    background: var(--color-white);
    color: var(--color-navy);
    font-family: var(--font-sans);
    font-size: 1rem;
    line-height: 1.5;
    -webkit-tap-highlight-color: transparent;
  }

  h1,
  h2,
  h3 {
16:  --color-tint: #f3f6fd; /* tiles inside white cards */
18:  --color-card-line: #e3e9f5; /* card and tile borders */
19:  --color-card-hover: #c9d5ee; /* a tappable card on hover */
42:  --text-card-question: 1.25rem;
43:  --text-card-question--line-height: 1.75rem;
44:  --text-card-question-lg: 1.5rem;
45:  --text-card-question-lg--line-height: 2rem;
56:  --radius-card: 20px;
72:  --shadow-card: 0 1px 2px rgb(6 27 77 / 0.04), 0 6px 20px rgb(6 27 77 / 0.06);
74:  --shadow-card-hover: 0 2px 4px rgb(6 27 77 / 0.06), 0 10px 28px rgb(6 27 77 / 0.1);

