import { redirect } from "next/navigation";
import { Suspense } from "react";
import { Screen } from "@/components/Screen";
import { Skeleton } from "@/components/Skeleton";
import { VisitCard } from "@/components/VisitCard";
import { copy } from "@/copy";
import { missingFor, providerName } from "@/server/booking";
import { getSession } from "@/server/sessions";
import { readVisitorId } from "@/server/visitor";
import { DetailsForm } from "./DetailsForm";
import { WhatIfCancel } from "./WhatIfCancel";

// Screen 5, the checkout's first step: the visit and "Your details". The
// full cost and the cancellation line come before the card (decided). On
// desktop the cost is in the path panel, so it shows once per layout
const FLOW = { phase: "book" as const, part: 1, parts: 2, back: "/join/provider" };

export default function BookPage() {
  return (
    <Suspense
      fallback={
        <Screen flow={FLOW} width="wide">
          <Skeleton rows={3} />
        </Screen>
      }
    >
      <Checkout />
    </Suspense>
  );
}

async function Checkout() {
  const visitorId = await readVisitorId();
  const session = visitorId ? await getSession(visitorId).catch(() => null) : null;
  const missing = missingFor(session, "provider");
  if (!session || missing || !session.slot_start || !session.provider_id) redirect(missing ?? "/join");
  if (session.booked_at) redirect("/join/booked");

  const insured = session.pay_method === "insurance";
  const provider = providerName(session.provider_id);
  return (
    <DetailsForm
      flow={{ ...FLOW, provider: { name: provider, slotStart: session.slot_start } }}
      visit={
        <section aria-labelledby="your-visit" className="flex flex-col gap-2 lg:card lg:p-5">
          <h1 id="your-visit" className="display text-page-title lg:text-question lg:tracking-normal">
            {copy.checkout.yourVisit}
          </h1>
          {/* Phones: two rows and the cost; desktop: three rows with icons, cost in the panel */}
          <div className="lg:hidden">
            <VisitCard slotStart={session.slot_start} provider={provider} rows={2}>
              <p className="text-body">{insured ? copy.checkout.insuredCost : copy.checkout.selfPayCost}</p>
              <p className="text-body">{insured ? copy.checkout.insuredCharged : copy.checkout.selfPayCharged}</p>
              <p className="text-body">{copy.checkout.freeToCancel}</p>
              <WhatIfCancel />
            </VisitCard>
          </div>
          <div className="hidden lg:block">
            <VisitCard slotStart={session.slot_start} provider={provider} icons bare>
              <p className="text-body">{copy.checkout.freeToCancel}</p>
              <WhatIfCancel />
            </VisitCard>
          </div>
        </section>
      }
    />
  );
}
              <FieldError>{copy.common.somethingWentWrong}</FieldError>
              <p className="text-body text-slate">{copy.common.keepsHappening}</p>
            </div>
          )}
          <Button type="submit" form="payment-form" disabled={booking} className="w-full">
            {failed ? copy.common.tryAgain : copy.checkout.bookMyVisit}
          </Button>
          <DemoLine>{copy.checkout.paymentLabel}</DemoLine>
        </div>
      }
    >
      <section aria-label={copy.checkout.yourVisit} className="card overflow-hidden">
        <button
          type="button"
          aria-expanded={open}
          aria-controls="visit-summary"
          onClick={() => setOpen(!open)}
          className="focus-ring flex w-full cursor-pointer items-center gap-3 px-4 py-3 text-left md:px-6"
        >
          <Calendar size={20} className="flex-none text-brand" />
          <span className="flex flex-1 flex-col">
            <span className="text-label font-semibold text-slate">{copy.checkout.yourVisit}</span>
            <span className="text-body font-semibold text-ink">{whenShort}</span>
          </span>
          <ChevronDown size={22} className={cx("flex-none text-action transition-transform duration-300", open && "rotate-180")} />
        </button>
        {open && (
          <div id="visit-summary" className="expand">
            <div className="px-4 pb-4 md:px-6">{summary}</div>
          </div>
        )}
      </section>

      {/* On phones the fields sit on the page, with the lock line beside the
          heading (board 08-Payment-M); a card from 768px up */}
      <Card className="gap-3 max-md:border-0 max-md:bg-transparent max-md:p-0 max-md:shadow-none">
        <section ref={section} aria-labelledby="payment-title" className="flex flex-col gap-3">
          <div className="flex flex-col gap-1 max-md:flex-row max-md:flex-wrap max-md:items-center max-md:justify-between max-md:gap-x-3">
            <h1 id="payment-title" className="display text-page-title md:text-card-question-lg">
              {copy.checkout.payment}
            </h1>
            <p className="flex items-center gap-2 text-body text-slate max-md:font-semibold max-md:text-ink">
              <Lock size={16} className="flex-none text-brand" />
              {copy.checkout.notCharged}
            </p>
          </div>
          <form id="payment-form" noValidate onSubmit={onSubmit} className="flex flex-col gap-2">
            <TextField
              id="card-number"
              label={copy.checkout.cardNumber}
              value={card.number}

