// Is the terms notice on details, before consent, and gone from payment?
import { chromium } from "playwright";
import { book } from "./book.mjs";
const BASE = process.env.BASE ?? "http://localhost:3400";
const W = Number(process.env.W ?? 390), H = Number(process.env.H ?? 700);
const b = await chromium.launch({ channel: "chrome" });
const c = await b.newContext({ viewport: { width: W, height: H }, ...(W < 768 ? { isMobile: true, hasTouch: true } : {}) });
await c.route(/posthog\.com|\/ingest\//, (r) => r.abort());
const p = await c.newPage();
const NOTICE = "By continuing, you agree to our Terms of Service";
const report = async (name) => {
  await p.waitForTimeout(1200);
  const r = await p.evaluate((n) => {
    const el = [...document.querySelectorAll("p")].find((e) => e.textContent.startsWith(n) && e.checkVisibility());
    const consent = [...document.querySelectorAll("label, span")].find((e) => e.textContent.startsWith("I consent") && e.checkVisibility());
    const f = [...document.querySelectorAll("div")].find((d) => getComputedStyle(d).position === "sticky" && d.checkVisibility());
    return {
      notice: !!el,
      beforeConsent: el && consent ? !!(el.compareDocumentPosition(consent) & Node.DOCUMENT_POSITION_FOLLOWING) : null,
      page: document.documentElement.scrollHeight,
      noticeBottom: el ? Math.round(el.getBoundingClientRect().bottom) : null,
      consentBottom: consent ? Math.round(consent.getBoundingClientRect().bottom) : null,
      footerTop: f ? Math.round(f.getBoundingClientRect().top) : null,
    };
  }, NOTICE);
  console.log(`${W}x${H} ${name}: ${JSON.stringify(r)}`);
  await p.screenshot({ path: new URL(`./shots/notice-${name}-${W}.png`, import.meta.url).pathname });
};
const origGoto = p.waitForURL.bind(p);
p.waitForURL = async (re, o) => {
  await origGoto(re, o);
  const s = String(re);
  if (s.includes("book$")) await report("details");
  if (s.includes("payment")) await report("payment");
};
await book(p, BASE);
console.log("booked:", new URL(p.url()).pathname);
await b.close();
EOF
