import { NextResponse, type NextRequest } from "next/server";
import { VISITOR_COOKIE, VISITOR_COOKIE_MAX_AGE } from "@/server/visitor";

// Gives every new visitor an anonymous id. It's set on the request as well as
// the response, so the page or route handling this first request can read it
export function proxy(request: NextRequest) {
  if (request.cookies.has(VISITOR_COOKIE)) return NextResponse.next();

  const visitorId = crypto.randomUUID();
  request.cookies.set(VISITOR_COOKIE, visitorId);

  const response = NextResponse.next({ request: { headers: request.headers } });
  response.cookies.set(VISITOR_COOKIE, visitorId, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: VISITOR_COOKIE_MAX_AGE,
  });
  return response;
}

export const config = {
  // Everything except build files and the icon
  matcher: ["/((?!_next/static|_next/image|icon.svg|favicon.ico).*)"],
};
"use client";

import { useRouter } from "next/navigation";
import { useLayoutEffect, useState } from "react";
import { Button, ButtonLink } from "@/components/Button";
import { FieldError } from "@/components/SegmentedControl";
import { copy } from "@/copy";
import { track } from "@/lib/analytics/track";

// "Mark visit completed" and "Mark no-show". Either can be changed afterwards,
// since it's a demo
type Outcome = "completed" | "no_show";

export function DemoControls({ intakeDone }: { intakeDone: boolean }) {
  const router = useRouter();
  const [marked, setMarked] = useState<Outcome | null>(null);
  const [busy, setBusy] = useState(false);
  const [failed, setFailed] = useState(false);

  // Next keeps this page alive; clear the last confirmation when it's hidden
  useLayoutEffect(
    () => () => {
      setMarked(null);
      setBusy(false);
      setFailed(false);
    },
    [],
  );

  const mark = async (outcome: Outcome) => {
    setBusy(true);
    setFailed(false);
    try {
      const response = await fetch("/api/demo/outcome", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ outcome }),
      });
      if (!response.ok) throw new Error(`outcome failed: ${response.status}`);
      // The north-star event, with whether the check-in was done
      if (outcome === "completed") track("portal.visit.completed", { intake_done: intakeDone });
      else track("portal.visit.no_show");
      setMarked(outcome);
      router.refresh();
    } catch {
      setFailed(true);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="flex flex-col items-stretch gap-2">
      <Button onClick={() => mark("completed")} disabled={busy} className="w-full">
        {copy.demo.markCompleted}
      </Button>
      <Button variant="secondary" onClick={() => mark("no_show")} disabled={busy} className="w-full">
        {copy.demo.markNoShow}
      </Button>
      <p role="status" className="text-body font-semibold text-ink">
import { cookies } from "next/headers";
import { NextResponse } from "next/server";
import { z } from "zod";
import { DEMO_POINTS } from "@/lib/portal/inbox";
import { DEMO_CLOCK_COOKIE } from "@/server/portal";
import { VISITOR_COOKIE_MAX_AGE } from "@/server/visitor";

// "Demo: skip to 72 hours" (then 24 and 1): moves the inbox's clock. Demo only
const Body = z.object({ to: z.enum(DEMO_POINTS) }).strict();

export async function POST(request: Request) {
  const parsed = Body.safeParse(await request.json().catch(() => null));
  if (!parsed.success) return NextResponse.json({ error: "bad_request" }, { status: 400 });

  (await cookies()).set(DEMO_CLOCK_COOKIE, parsed.data.to, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: VISITOR_COOKIE_MAX_AGE,
  });
  return NextResponse.json({ ok: true });
}
