  if (!(await box.count())) { console.log("no text box on this question"); await shot(`q${i + 1}-other`); break; }
  await box.fill(answers[i]);
  await p.getByRole("button", { name: /Next|Send my answers|Continue/ }).first().click();
  // capture the transition into the next question
  for (const t of [150, 400, 900, 2500, 5000]) {
    await p.waitForTimeout(t === 150 ? 150 : t - [150, 400, 900, 2500, 5000][[150, 400, 900, 2500, 5000].indexOf(t) - 1]);
    await shot(`q${i + 2}-${t}ms`);
  }
}
