import { book } from "./book.mjs";
const BASE = process.env.BASE ?? "http://localhost:3400";
const W = Number(process.env.W ?? 390), H = Number(process.env.H ?? 844);
const b = await chromium.launch({ channel: "chrome" });
const c = await b.newContext({ viewport: { width: W, height: H }, ...(W < 768 ? { isMobile: true, hasTouch: true } : {}) });
await c.route(/posthog\.com|\/ingest\//, (r) => r.abort());
const p = await c.newPage();
const shot = (n) => p.screenshot({ path: new URL(`./shots/checkin-${n}-${W}.png`, import.meta.url).pathname });
await book(p, BASE);
await p.goto(`${BASE}/visit`);
await p.getByRole("button", { name: /Demo: skip to 72 hours/ }).click();
await p.waitForTimeout(1500);
await p.getByRole("link", { name: "Start check-in" }).first().click();
await p.waitForURL(/check-in/);
await p.waitForTimeout(2500);
await shot("q1");
const box = p.locator("#check-in-answer");
const answers = ["My Adderall ran out two weeks ago and I can't focus at work.", "Adderall 20mg once a day, prescribed last year.", "No"];
for (let i = 0; i < 3; i++) {
  const step = await p.evaluate(() => document.querySelector("form#check-in-form label, form#check-in-form legend, h1")?.textContent?.slice(0, 70));
  console.log(`q${i + 1}:`, step);
  if (!(await box.count())) { console.log("no text box on this question"); await shot(`q${i + 1}-other`); break; }
  await box.fill(answers[i]);
  await p.getByRole("button", { name: /Next|Send my answers|Continue/ }).first().click();
  // capture the transition into the next question
  for (const t of [150, 400, 900, 2500, 5000]) {
    await p.waitForTimeout(t === 150 ? 150 : t - [150, 400, 900, 2500, 5000][[150, 400, 900, 2500, 5000].indexOf(t) - 1]);
    await shot(`q${i + 2}-${t}ms`);
  }
}
await b.close();
