"use client";

import { type ReactNode, useId } from "react";
import { cx } from "./cx";
import { FieldError } from "./SegmentedControl";

// For yes-or-no choices inside the flow: "Tell me if an earlier time opens",
// the consent and "I'm safe right now". A native checkbox in the spec's
// colours: a 24px box in a 44px tap row, with optional error text. The label
// can hold a link, like "Read the consent"
export type CheckboxProps = {
  label: ReactNode;
  checked: boolean;
  onChange: (next: boolean) => void;
  error?: string;
};

export function Checkbox({ label, checked, onChange, error }: CheckboxProps) {
  const id = useId();
  const errorId = error ? `${id}-error` : undefined;

  return (
    <div className="flex flex-col gap-1.5">
      <div className="flex min-h-control-sm items-start gap-3">
        <span className="relative mt-2.5 flex size-6 flex-none">
          <input
            id={id}
            type="checkbox"
            checked={checked}
            onChange={(event) => onChange(event.target.checked)}
            aria-invalid={error ? true : undefined}
            aria-describedby={errorId}
            className={cx(
              "focus-ring peer size-6 cursor-pointer appearance-none rounded-md border-[1.5px] bg-white",
              "checked:border-action checked:bg-action",
              error ? "border-2 border-error" : "border-line-control hover:border-action",
            )}
          />
          <svg
            className="pointer-events-none absolute inset-0 m-auto hidden size-4 text-white peer-checked:block"
            viewBox="0 0 16 16"
            fill="none"
            stroke="currentColor"
            strokeWidth="2.5"
            strokeLinecap="round"
// Puts a link into its sentence: a tap-to-call number or a website. The copy
// keeps the whole sentence with a placeholder ("Call us at {number}."), so the
// readability check reads it as one string. The pseudo-element gives a short
// link like "988" a 44px tap area without changing the line height
export const InlineLink = ({
  text,
  label,
  href,
  placeholder = "{number}",
}: {
  text: string;
  label: string;
  href: string;
  placeholder?: string;
}) => {
  const [before, after] = text.split(placeholder);
  return (
    <>
      {before}
      <a
        href={href}
        className="focus-ring relative rounded-sm font-medium whitespace-nowrap text-action underline underline-offset-4 hover:text-action-hover after:absolute after:-inset-x-2 after:-inset-y-3.5 after:content-['']"
      >
        {label}
      </a>
      {after}
    </>
  );
};
