  "portal.appointment.confirmed": { days_to_visit: number };
  "portal.calendar.added": { calendar: "google" | "apple" | "outlook" };
  "portal.visit_page.viewed": Record<string, never>;
  "portal.intake.invited": Record<string, never>;
