  get diagnostics n = row_count;
  if n <> 33 then raise exception 'ai_calls: expected 33, would delete %', n; end if;

  delete from public.onboarding_sessions
  where id in ('b7192e3c-266b-4eaf-8bb5-d661b85049c5', '4577d7db-1a94-4b69-8305-971432097760')
