// Captures the PostHog events the app tries to send, without sending them
import { chromium } from "playwright";
import zlib from "node:zlib";
const BASE = process.env.BASE ?? "http://localhost:3400";
const b = await chromium.launch({ channel: "chrome" });

async function visitor(name, run) {
  const c = await b.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  const seen = [];
  await c.route(/posthog\.com|\/ingest\//, async (route) => {
    const req = route.request();
    const body = req.postDataBuffer();
    if (body) {
      let text = null;
      for (const tryIt of [() => zlib.gunzipSync(body).toString(), () => body.toString(), () => Buffer.from(decodeURIComponent(body.toString().replace(/^data=/, "")), "base64").toString()]) {
        try { const t = tryIt(); JSON.parse(t); text = t; break; } catch {}
      }
      if (text) {
        const data = JSON.parse(text);
        for (const e of Array.isArray(data) ? data : data.batch ?? [data]) {
          if (!e?.event?.startsWith("portal.")) continue;
          const props = Object.fromEntries(Object.entries(e.properties ?? {}).filter(([k]) => !k.startsWith("$") && k !== "token" && k !== "distinct_id"));
          seen.push(`${e.event} ${JSON.stringify(props)}`);
        }
      }
    }
    await route.fulfill({ status: 200, contentType: "application/json", body: '{"status":1}' });
  });
  const p = await c.newPage();
  await run(p);
  await p.waitForTimeout(4000); // let PostHog flush its batch
  await p.evaluate(() => window.dispatchEvent(new Event("pagehide")));
  await p.waitForTimeout(1500);
  console.log(`\n${name}:`);
  for (const s of seen) if (/fit\.|onboarding\.|crisis/.test(s)) console.log("  " + s);
  await c.close();
}
const answer = (p, q, a) => p.getByRole("group", { name: q }).getByText(a, { exact: true }).click();

await visitor("Tap No to Texas", async (p) => {
  await p.goto(`${BASE}/join`);
  await p.getByLabel("Date of birth").pressSequentially("01151990");
  await answer(p, "Will you be in Texas for your visits?", "No");
  await p.waitForURL(/not-a-fit/);
});
await visitor("Under 18, then Continue", async (p) => {
  await p.goto(`${BASE}/join`);
  await p.getByLabel("Date of birth").pressSequentially("01152012");
  await answer(p, "Will you be in Texas for your visits?", "Yes");
  await p.getByRole("button", { name: "Continue", exact: true }).click();
  await p.waitForURL(/not-a-fit/);
});
await visitor("Medicaid from the plan list", async (p) => {
  await p.goto(`${BASE}/join`);
  await p.getByLabel("Date of birth").pressSequentially("01151990");
  await answer(p, "Will you be in Texas for your visits?", "Yes");
  await p.getByRole("button", { name: "Continue", exact: true }).click();
  await p.waitForURL(/insurance/);
  await answer(p, "Do you have health insurance?", "Yes");
  await p.getByRole("radio", { name: "Medicaid" }).click();
  await p.waitForURL(/not-a-fit/);
});
await visitor("Eligible through safety", async (p) => {
  await p.goto(`${BASE}/join`);
  await p.getByLabel("Date of birth").pressSequentially("01151990");
  await answer(p, "Will you be in Texas for your visits?", "Yes");
  await p.getByRole("button", { name: "Continue", exact: true }).click();
  await p.waitForURL(/insurance/);
  await answer(p, "Do you have health insurance?", "Yes");
  await p.getByRole("radio", { name: "Aetna", exact: true }).click();
  await p.getByRole("button", { name: "Continue", exact: true }).click();
  await p.waitForURL(/your-plan/);
  await p.getByRole("link", { name: "Continue" }).first().click();
  await p.waitForURL(/safety/);
  await answer(p, "Are you thinking about harming yourself or others?", "No");
  await p.getByRole("group").nth(1).getByText("No", { exact: true }).click();
  await p.getByRole("button", { name: "Continue", exact: true }).click();
  await p.waitForURL(/whats-going-on/);
});
await visitor("Yes to the safety question", async (p) => {
  await p.goto(`${BASE}/join`);
  await p.getByLabel("Date of birth").pressSequentially("01151990");
  await answer(p, "Will you be in Texas for your visits?", "Yes");
  await p.getByRole("button", { name: "Continue", exact: true }).click();
  await p.waitForURL(/insurance/);
  await answer(p, "Do you have health insurance?", "No");
  await p.getByRole("group", { name: /Medicaid or Medicare/ }).getByText("No", { exact: true }).click();
  await p.getByRole("button", { name: "Continue", exact: true }).click();
  await p.waitForURL(/safety/);
  await answer(p, "Are you thinking about harming yourself or others?", "Yes");
  await p.waitForURL(/help-now/);
});
await b.close();
