cd /private/tmp/claude-501/-Users-lilytewolde-Projects-legion-onboarding/6de9b28e-88d2-48d2-8e9d-e0d522c68144/scratchpad/pw && cat > arrows.mjs <<'EOF'
// Keyboard on the Yes/No questions: arrows only select; Space, Enter or Continue act
import { chromium } from "playwright";
import zlib from "node:zlib";
const BASE = process.env.BASE ?? "http://localhost:3400";
const b = await chromium.launch({ channel: "chrome" });

async function run(name, steps) {
  const c = await b.newContext({ viewport: { width: 1440, height: 900 } });
  await c.addInitScript(() => Object.defineProperty(Navigator.prototype, "webdriver", { get: () => false }));
  const sent = [];
  await c.route(/posthog\.com|\/ingest\//, async (route) => {
    const body = route.request().postDataBuffer();
    if (body) {
      for (const f of [() => zlib.gunzipSync(body).toString(), () => body.toString()]) {
        try { const d = JSON.parse(f()); for (const e of Array.isArray(d) ? d : d.batch ?? [d]) if (e?.event?.startsWith("portal.fit") || e?.event?.startsWith("portal.crisis")) sent.push(e.event); break; } catch {}
      }
    }
    await route.fulfill({ status: 200, contentType: "application/json", body: '{"status":1}' });
  });
  const p = await c.newPage();
  const out = await steps(p);
  await p.waitForTimeout(3500);
  console.log(`${name}: ${out} | events: ${sent.join(", ") || "none"}`);
  await c.close();
}
const radio = (p, q, a) => p.getByRole("group", { name: q }).getByRole("radio", { name: a, exact: true });
const atJoin = async (p) => { await p.goto(`${BASE}/join`); await p.getByLabel("Date of birth").pressSequentially("01151990"); };
const TEXAS = "Will you be in Texas for your visits?";

await run("Texas: focus Yes, ArrowRight to No", async (p) => {
  await atJoin(p);
  await radio(p, TEXAS, "Yes").focus(); await p.keyboard.press("Space"); await p.waitForTimeout(300);
  await p.keyboard.press("ArrowRight"); await p.waitForTimeout(1200);
  return `path ${new URL(p.url()).pathname}, No checked ${await radio(p, TEXAS, "No").isChecked()}`;
});
await run("Texas: ArrowRight to No, then Space", async (p) => {
  await atJoin(p);
  await radio(p, TEXAS, "Yes").focus(); await p.keyboard.press("Space"); await p.waitForTimeout(300);
  await p.keyboard.press("ArrowRight"); await p.waitForTimeout(500);
  await p.keyboard.press("Space"); await p.waitForTimeout(1500);
  return `path ${new URL(p.url()).pathname}`;
});
await run("Texas: ArrowRight to No, then Enter", async (p) => {
  await atJoin(p);
  await radio(p, TEXAS, "Yes").focus(); await p.keyboard.press("Space"); await p.waitForTimeout(300);
  await p.keyboard.press("ArrowRight"); await p.waitForTimeout(500);
  await p.keyboard.press("Enter"); await p.waitForTimeout(1500);
  return `path ${new URL(p.url()).pathname}`;
});
await run("Texas: ArrowRight to No, then Continue", async (p) => {
  await atJoin(p);
  await radio(p, TEXAS, "Yes").focus(); await p.keyboard.press("Space"); await p.waitForTimeout(300);
  await p.keyboard.press("ArrowRight"); await p.waitForTimeout(500);
  await p.getByRole("button", { name: "Continue", exact: true }).click(); await p.waitForTimeout(1500);
  return `path ${new URL(p.url()).pathname}`;
});
await run("Texas: click No", async (p) => {
  await atJoin(p);
  await p.getByRole("group", { name: TEXAS }).getByText("No", { exact: true }).click(); await p.waitForTimeout(1500);
  return `path ${new URL(p.url()).pathname}`;
});
await run("Safety: focus No, ArrowLeft to Yes", async (p) => {
  await atJoin(p);
  await p.getByRole("group", { name: TEXAS }).getByText("Yes", { exact: true }).click();
  await p.getByRole("button", { name: "Continue", exact: true }).click(); await p.waitForURL(/insurance/);
  await p.getByRole("group", { name: "Do you have health insurance?" }).getByText("No", { exact: true }).click();
  await p.getByRole("group", { name: /Medicaid or Medicare/ }).getByText("No", { exact: true }).click();
  await p.getByRole("button", { name: "Continue", exact: true }).click(); await p.waitForURL(/safety/);
  const q = "Are you thinking about harming yourself or others?";
  await radio(p, q, "No").focus(); await p.keyboard.press("Space"); await p.waitForTimeout(300);
  await p.keyboard.press("ArrowLeft"); await p.waitForTimeout(1200);
  const stayed = new URL(p.url()).pathname;
  await p.keyboard.press("Enter"); await p.waitForTimeout(1500);
  return `after arrow: ${stayed}, after Enter: ${new URL(p.url()).pathname}`;
});
await b.close();
EOF
sleep 1; node arrows.mjs

