await c.route(/posthog\.com|\/ingest\//, (r) => r.abort());
await c.addInitScript(() => {
  class FakeRecognition {
    constructor() { window.__rec = this; this.stopped = false; }
    start() {}
    stop() { this.stopped = true; }
  }
  window.webkitSpeechRecognition = FakeRecognition;
  window.__say = (text, isFinal) => window.__rec?.onresult?.({ resultIndex: 0, results: [{ isFinal, 0: { transcript: text } }] });
});
const p = await c.newPage();
const answer = (q, a) => p.getByRole("group", { name: q }).getByText(a, { exact: true }).click();
await p.goto(`${BASE}/join`);
