await answer("Will you be in Texas for your visits?", "Yes");
await p.getByRole("button", { name: "Continue", exact: true }).click();
await p.waitForURL(/insurance/);
await answer("Do you have health insurance?", "No");
await p.getByRole("group", { name: /Medicaid or Medicare/ }).getByText("No", { exact: true }).click();
await p.getByRole("button", { name: "Continue", exact: true }).click();
await p.waitForURL(/safety/);
await answer("Are you thinking about harming yourself or others?", "No");
await p.getByRole("group").nth(1).getByText("No", { exact: true }).click();
await p.getByRole("button", { name: "Continue", exact: true }).click();
await p.waitForURL(/whats-going-on/);
await p.waitForTimeout(800);
const box = p.locator("textarea").first();
const state = async (label) => {
  const r = await p.evaluate(() => {
    const t = document.querySelector("textarea");
    const status = [...document.querySelectorAll("[role=status]")].map((e) => e.textContent.trim()).filter(Boolean);
    const overlay = t.parentElement.querySelectorAll("div[aria-hidden=true]").length;
    return { height: Math.round(t.getBoundingClientRect().height), value: t.value, placeholder: t.placeholder, readOnly: t.readOnly, status, overlay, stopped: window.__rec?.stopped ?? null };
  });
  console.log(label.padEnd(34), JSON.stringify(r));
};
await state("before");
await box.fill("I can't sleep.");
await p.getByRole("button", { name: "Speak" }).click();
await p.waitForTimeout(300);
await state("tapped mic, nothing said yet");
await p.screenshot({ path: new URL("./shots/mic-1-listening.png", import.meta.url).pathname, clip: { x: 0, y: 100, width: 390, height: 300 } });
await p.evaluate(() => window.__say("and my medication ran out last week", false)); await p.waitForTimeout(200);
await state("interim words");
await p.evaluate(() => window.__say("and my medication ran out last week so I've been struggling to focus at work and at home and I keep waking up at night", false)); await p.waitForTimeout(200);
await state("longer interim");
await p.screenshot({ path: new URL("./shots/mic-2-growing.png", import.meta.url).pathname, clip: { x: 0, y: 100, width: 390, height: 400 } });
await p.waitForTimeout(4500);
await state("4.5s of silence");
await p.screenshot({ path: new URL("./shots/mic-3-stopped.png", import.meta.url).pathname, clip: { x: 0, y: 100, width: 390, height: 400 } });
await box.fill("");
await p.getByRole("button", { name: "Speak" }).click();
await p.waitForTimeout(8500);
await state("8.5s, nothing said");
await p.getByRole("button", { name: "Speak" }).click();
await p.evaluate(() => window.__say("I have ADHD", true)); await p.waitForTimeout(200);
await p.getByRole("button", { name: "Speak" }).click(); await p.waitForTimeout(300);
