-- Deletes the hand-pass test person lilyatewolde+legion@gmail.com and
-- everything keyed to them, by exact id. If any count isn't what the lookup
-- found, it raises and nothing is deleted.
begin;

do $$
declare
  n integer;
begin
  delete from public.ai_calls
  where anon_id in (
    select anon_id from public.onboarding_sessions
    where id = '01ab7afe-9a8c-4d64-bb71-6c40c691ebb4'
  );
  get diagnostics n = row_count;
  if n <> 19 then raise exception 'ai_calls: expected 19, would delete %', n; end if;

  delete from public.onboarding_sessions
  where id = '01ab7afe-9a8c-4d64-bb71-6c40c691ebb4'
    and person_id = 'b1b1c363-1e55-45c0-b737-5787aa360ead';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'onboarding_sessions: expected 1, would delete %', n; end if;

  delete from public.people
  where id = 'b1b1c363-1e55-45c0-b737-5787aa360ead'
    and email = 'lilyatewolde+legion@gmail.com';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'people: expected 1, would delete %', n; end if;

  raise notice 'Deleted 19 ai_calls rows, 1 session and 1 person';
end $$;

