// Samples every frame during transitions: does the frame hold still, and how do content elements move?
import { chromium } from "playwright";
import { book } from "./book.mjs";
const BASE = process.env.BASE ?? "http://localhost:3400";
const b = await chromium.launch({ channel: "chrome" });

const install = (p) => p.evaluate(() => {
  window.__frames = [];
  const tick = () => {
    const vis = (el) => el && el.checkVisibility();
    const frame = {
      header: document.querySelector("header"),
      stepper: [...document.querySelectorAll("[role=progressbar]")].find(vis)?.parentElement,
      footer: [...document.querySelectorAll(".screen .sticky")].find(vis),
      panel: [...document.querySelectorAll("aside")].find(vis),
      tabbar: [...document.querySelectorAll("nav")].find((n) => vis(n) && getComputedStyle(n.parentElement).position === "sticky"),
    };
    const rect = {};
    for (const [k, el] of Object.entries(frame)) if (vis(el)) { const r = el.getBoundingClientRect(); rect[k] = `${Math.round(r.x)},${Math.round(r.y)}`; }
    const body = [...document.querySelectorAll(".screen-body")].find(vis);
    const kids = body ? [...body.children].filter((c) => !c.classList.contains("still")).slice(0, 4) : [];
    const content = kids.map((c) => { const m = new DOMMatrixReadOnly(getComputedStyle(c).transform); return `${Math.round(m.m41)}px/${(+getComputedStyle(c).opacity).toFixed(2)}`; });
    const screenT = [...document.querySelectorAll(".screen")].filter(vis).map((s) => getComputedStyle(s).transform);
    window.__frames.push({ path: location.pathname, rect, content, screenMoved: screenT.some((t) => t !== "none") });
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
});
const report = async (p, label) => {
  const f = await p.evaluate(() => window.__frames);
  const after = f.filter((x) => x.path === f[f.length - 1].path);
  const moved = {};
  for (const k of ["header", "stepper", "footer", "panel", "tabbar"]) {
    const vals = new Set(after.map((x) => x.rect[k]).filter(Boolean));
    if (vals.size) moved[k] = vals.size === 1 ? "still" : `MOVED (${[...vals].slice(0, 3).join(" ")})`;
  }
  const firstContent = after.find((x) => x.content.length)?.content ?? [];
  const xs = new Set(after.flatMap((x) => x.content.map((c) => c.split("/")[0])));
  console.log(`${label}: frame ${JSON.stringify(moved)} | .screen moved: ${after.some((x) => x.screenMoved)} | content first frame [${firstContent.join(", ")}] | offsets seen ${[...xs].join(" ")}`);
  await p.evaluate(() => (window.__frames = []));
};

for (const [w, h] of [[390, 844], [1440, 900]]) {
  const c = await b.newContext({ viewport: { width: w, height: h }, ...(w < 768 ? { isMobile: true, hasTouch: true } : {}) });
  await c.route(/posthog\.com|\/ingest\//, (r) => r.abort());
  const p = await c.newPage();
  const answer = (q, a) => p.getByRole("group", { name: q }).getByText(a, { exact: true }).click();
  await p.goto(`${BASE}/join`);
  await p.waitForTimeout(600);
  await install(p);
  await p.getByLabel("Date of birth").pressSequentially("01151990");
  await answer("Will you be in Texas for your visits?", "Yes");
  await p.evaluate(() => (window.__frames = []));
  await p.getByRole("button", { name: "Continue", exact: true }).click();
  await p.waitForURL(/insurance/); await p.waitForTimeout(900);
  await report(p, `${w} forward /join -> insurance`);
  await p.goBack(); await p.waitForURL(/\/join$/); await p.waitForTimeout(900);
  await report(p, `${w} back insurance -> /join`);
  await book(p, BASE);
  await p.goto(`${BASE}/visit`); await p.waitForTimeout(1200);
  await install(p);
  await p.evaluate(() => (window.__frames = []));
  await p.getByRole("link", { name: /Inbox/ }).first().click();
  await p.waitForURL(/inbox/); await p.waitForTimeout(900);
  await report(p, `${w} tab Visit -> Inbox`);
  await p.getByRole("link", { name: /Profile/ }).first().click();
  await p.waitForURL(/profile/); await p.waitForTimeout(900);
  await report(p, `${w} tab Inbox -> Profile`);
  await c.close();
}
await b.close();
EOF
