// Desktop panel: how far does the card run past its last item?
import { chromium } from "playwright";
import { book } from "./book.mjs";
const BASE = process.env.BASE ?? "http://localhost:3400";
const b = await chromium.launch({ channel: "chrome" });
const c = await b.newContext({ viewport: { width: 1440, height: 900 } });
await c.route(/posthog\.com|\/ingest\//, (r) => r.abort());
const p = await c.newPage();
const measure = async (name) => {
  await p.waitForTimeout(900);
  const r = await p.evaluate(() => {
    const aside = [...document.querySelectorAll("aside")].find((a) => a.checkVisibility());
    if (!aside) return null;
    const last = [...aside.querySelectorAll("p, li, h2")].filter((e) => e.checkVisibility()).reduce((m, e) => Math.max(m, e.getBoundingClientRect().bottom), 0);
    const box = aside.getBoundingClientRect();
    return { panelBottom: Math.round(box.bottom), lastItemBottom: Math.round(last), gapBelowLastItem: Math.round(box.bottom - last), page: document.documentElement.scrollHeight };
  });
  console.log(name.padEnd(26), JSON.stringify(r));
};
const seen = new Set();
const orig = p.waitForURL.bind(p);
p.waitForURL = async (re, o) => { await orig(re, o); const k = String(re); if (!seen.has(k)) { seen.add(k); await measure(k); } };
await p.goto(`${BASE}/join`); await measure("/join");
await book(p, BASE);
await measure("booked");
await p.screenshot({ path: new URL("./shots/panel-fit-booked.png", import.meta.url).pathname });
await b.close();
EOF
