sleep 3; cd /private/tmp/claude-501/-Users-lilytewolde-Projects-legion-onboarding/6de9b28e-88d2-48d2-8e9d-e0d522c68144/scratchpad/pw && cat > cal-icons.mjs <<'EOF'
import { chromium } from "playwright";
import { book } from "./book.mjs";
const BASE = process.env.BASE ?? "http://localhost:3400";
const b = await chromium.launch({ channel: "chrome" });
const shotBox = (p) => p.evaluate(() => { const a = [...document.querySelectorAll("a[aria-label^='Add to']")].filter((e) => e.checkVisibility()); const r = a.map((e) => e.getBoundingClientRect()); const x = Math.min(...r.map((q) => q.x)) - 12, y = Math.min(...r.map((q) => q.y)) - 12; return { x, y, width: Math.max(...r.map((q) => q.right)) - x + 12, height: Math.max(...r.map((q) => q.bottom)) - y + 12 }; });
const state = (p) => p.evaluate(() => [...document.querySelectorAll("a[aria-label^='Add to']")].filter((e) => e.checkVisibility()).map((a) => { const img = a.querySelector("img"); return `${a.getAttribute("aria-label")}: ${img ? (img.complete && img.naturalWidth > 0 ? "icon loaded" : "icon FAILED") : "placeholder"}, name ${a.querySelector("span.hidden.md\\:inline")?.checkVisibility() ? "shown" : "hidden"}`; }));
for (const [w, h, block] of [[390, 844, false], [1440, 900, false], [1440, 900, true]]) {
  const c = await b.newContext({ viewport: { width: w, height: h }, ...(w < 768 ? { isMobile: true, hasTouch: true } : {}) });
  await c.route(/posthog\.com|\/ingest\//, (r) => r.abort());
  if (block) await c.route(/\/icons\//, (r) => r.abort());
  const p = await c.newPage();
  await book(p, BASE);
  await p.waitForTimeout(1500);
  const tag = `${w}${block ? "-blocked" : ""}`;
  console.log(`booked ${tag}:`, JSON.stringify(await state(p)));
  await p.screenshot({ path: new URL(`./shots/cal-booked-${tag}.png`, import.meta.url).pathname, clip: await shotBox(p) });
  if (!block) {
    await p.goto(`${BASE}/visit`); await p.waitForTimeout(1500);
    const vis = await state(p);
    console.log(`visit ${tag}:`, JSON.stringify(vis));
    if (vis.length) await p.screenshot({ path: new URL(`./shots/cal-visit-${tag}.png`, import.meta.url).pathname, clip: await shotBox(p) });
  }
  await c.close();
}
await b.close();
EOF
