// The plan list: does any name wrap, and how much room does it have?
import { chromium } from "playwright";
const BASE = process.env.BASE ?? "http://localhost:3400";
const b = await chromium.launch({ channel: "chrome" });
for (const [w, h] of [[390, 700], [390, 844], [768, 1024], [1024, 768], [1440, 900]]) {
  const c = await b.newContext({ viewport: { width: w, height: h }, ...(w < 768 ? { isMobile: true, hasTouch: true } : {}) });
  await c.route(/posthog\.com|\/ingest\//, (r) => r.abort());
  const p = await c.newPage();
  const answer = (q, a) => p.getByRole("group", { name: q }).getByText(a, { exact: true }).click();
  await p.goto(`${BASE}/join`);
  await p.getByLabel("Date of birth").pressSequentially("01151990");
  await answer("Will you be in Texas for your visits?", "Yes");
  await p.getByRole("button", { name: "Continue", exact: true }).click();
  await p.waitForURL(/insurance/);
  await answer("Do you have health insurance?", "Yes");
  await p.waitForTimeout(800);
  const rows = await p.evaluate(() => [...document.querySelectorAll("[role=radiogroup] [role=radio]")].map((r) => {
    const textNode = [...r.childNodes].find((n) => n.nodeType === 3 && n.textContent.trim());
    const range = document.createRange(); range.selectNodeContents(textNode);
    const lines = new Set([...range.getClientRects()].map((q) => Math.round(q.top))).size;
    const textW = Math.round(range.getBoundingClientRect().width);
    const cs = getComputedStyle(r); const logo = r.querySelector("span[aria-hidden]")?.getBoundingClientRect().width ?? 0;
    const room = Math.round(r.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight) - logo - parseFloat(cs.columnGap || cs.gap || 0));
    return `${textNode.textContent.trim()}: ${lines} line(s), ${Math.round(r.getBoundingClientRect().height)}px, text ${textW}px of ${room}px room`;
  }));
  const fit = await p.evaluate(() => { const b = [...document.querySelectorAll("button")].find((e) => e.checkVisibility() && /(^|\s)bg-action(\s|$)/.test(e.className)); return { page: document.documentElement.scrollHeight, continueBottom: Math.round(b.getBoundingClientRect().bottom) }; });
  console.log(`${w}x${h}`, JSON.stringify(fit)); for (const r of rows.filter((r) => /Blue|United|Aetna/.test(r))) console.log("   ", r);
  if (w === 1440) await p.screenshot({ path: new URL(`./shots/bcbs-${process.env.TAG ?? "x"}.png`, import.meta.url).pathname, clip: { x: 460, y: 330, width: 640, height: 420 } });
  await c.close();
}
await b.close();
EOF
